// GENERATED by scripts/sync-skill.mjs from prototype/palette.js. Edit the prototype, not this copy.
// Palette quantisation and pixel-art post passes on raw RGBA buffers. Pure:
// works on any { data: Uint8ClampedArray, width, height } (ImageData-shaped).

/** '#rrggbb' or '#rgb' -> [r, g, b]. Throws on anything else. */
export function hexToRgb(hex) {
  const m = /^#?([0-9a-f]{3}|[0-9a-f]{6})$/i.exec(String(hex).trim());
  if (!m) throw new Error(`bad colour ${hex}`);
  let h = m[1];
  if (h.length === 3) h = [...h].map((c) => c + c).join('');
  const n = parseInt(h, 16);
  return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

/** Unique list of [r,g,b] from hex strings (order kept). */
export function buildPalette(hexes) {
  const seen = new Set();
  const out = [];
  for (const h of hexes) {
    const rgb = hexToRgb(h);
    const key = rgb.join(',');
    if (seen.has(key)) continue;
    seen.add(key);
    out.push(rgb);
  }
  if (!out.length) throw new Error('empty palette');
  return out;
}

/** Index of the perceptually nearest palette colour (weighted RGB, "redmean"). */
export function nearestIndex(palette, r, g, b) {
  let best = 0;
  let bestD = Infinity;
  for (let i = 0; i < palette.length; i++) {
    const [pr, pg, pb] = palette[i];
    const rm = (r + pr) / 2;
    const dr = r - pr;
    const dg = g - pg;
    const db = b - pb;
    const d = (2 + rm / 256) * dr * dr + 4 * dg * dg + (2 + (255 - rm) / 256) * db * db;
    if (d < bestD) {
      bestD = d;
      best = i;
    }
  }
  return best;
}

/**
 * In place: snap every pixel to the palette, and alpha to 0/255 at `alphaCut`.
 * cache: optional Map reused across frames (rgb int -> palette index).
 * Returns the number of opaque pixels.
 */
export function quantize(img, palette, alphaCut = 128, cache = new Map()) {
  const d = img.data;
  let opaque = 0;
  for (let i = 0; i < d.length; i += 4) {
    if (d[i + 3] < alphaCut) {
      d[i + 3] = 0;
      continue;
    }
    const key = (d[i] << 16) | (d[i + 1] << 8) | d[i + 2];
    let idx = cache.get(key);
    if (idx === undefined) {
      idx = nearestIndex(palette, d[i], d[i + 1], d[i + 2]);
      cache.set(key, idx);
    }
    const c = palette[idx];
    d[i] = c[0];
    d[i + 1] = c[1];
    d[i + 2] = c[2];
    d[i + 3] = 255;
    opaque++;
  }
  return opaque;
}

/**
 * In place: every transparent pixel 4-adjacent to an opaque one becomes `rgb`
 * (a 1px silhouette outline, the classic sprite read at small sizes).
 * Returns the number of outline pixels written.
 */
export function outlinePass(img, rgb) {
  const { width: w, height: h, data: d } = img;
  const solid = new Uint8Array(w * h);
  for (let i = 0; i < w * h; i++) solid[i] = d[i * 4 + 3] > 0 ? 1 : 0;
  let n = 0;
  for (let y = 0; y < h; y++) {
    for (let x = 0; x < w; x++) {
      const i = y * w + x;
      if (solid[i]) continue;
      const near = (x > 0 && solid[i - 1]) || (x < w - 1 && solid[i + 1]) || (y > 0 && solid[i - w]) || (y < h - 1 && solid[i + w]);
      if (!near) continue;
      d[i * 4] = rgb[0];
      d[i * 4 + 1] = rgb[1];
      d[i * 4 + 2] = rgb[2];
      d[i * 4 + 3] = 255;
      n++;
    }
  }
  return n;
}
